package dev.veltraph.client.fishing.offense;

import org.junit.jupiter.api.Test;
import java.util.List;
import static org.junit.jupiter.api.Assertions.*;
import static dev.veltraph.client.fishing.offense.FishingOffenseController.Action.*;

final class FishingOffenseControllerTest {
    private final FishingOffenseProfile profile=new FishingOffenseProfile("minecraft:diamond_sword","Private Skill",List.of("Private ordinary-use skill"),"minecraft:zombie","Skill {target}",100,100L,200L,5000L,2);
    private FishingOffenseController.Frame frame(long now,boolean valid,boolean bobber,boolean held,boolean fresh,Integer mana,long revision,long ability,float health,float pitch,double h,double v,boolean rod,boolean spot,boolean view){return new FishingOffenseController.Frame(now,valid,true,health>0,h,v,bobber,true,held,fresh,mana,revision,ability,health,pitch,true,rod,spot,view,true);}
    private FishingOffenseController.Frame ready(long now){return frame(now,true,false,true,true,300,1,0,20,82,3.9,5.9,false,false,false);}
    private FishingOffenseController started(){var c=new FishingOffenseController();assertTrue(c.start(ready(0),profile,100));assertEquals(NONE,c.tick(ready(1),100));assertEquals(SELECT,c.tick(ready(2),100));return c;}
    private FishingOffenseController.Frame footing(FishingOffenseController.Frame f,boolean ready){return new FishingOffenseController.Frame(f.now(),f.valid(),f.targetIdentity(),f.targetAlive(),f.horizontal(),f.vertical(),f.bobber(),f.toolAvailable(),f.toolHeld(),f.manaFresh(),f.mana(),f.manaRevision(),f.abilityRevision(),f.targetHealth(),f.pitch(),f.clear(),f.rodRestored(),f.positionReturned(),f.viewReturned(),ready);}
    @Test void nativeKnockbackCannotImmediatelyStartGroundReturn(){
        var one=new FishingOffenseProfile(profile.itemId(),profile.itemName(),profile.itemLore(),profile.targetType(),profile.abilityReceiptTemplate(),100,100L,200L,5000L,1);
        var c=new FishingOffenseController();c.start(ready(0),one,100);c.tick(ready(1),100);c.tick(ready(2),100);c.tick(ready(100),100);
        c.tick(footing(frame(101,true,false,true,true,200,2,1,10,82,1,1,false,false,false),false),100);
        assertEquals(RESTORE_SLOT,c.tick(footing(frame(102,true,false,true,true,200,2,1,10,82,1,1,false,false,false),false),100));
        assertEquals(WAIT_FOOTING,c.tick(footing(frame(103,true,false,false,true,200,2,1,10,82,1,1,true,false,false),false),100),"Native acknowledged knockback must not send unsupported startnode to ground navigation");
    }
    private FishingOffenseController waitingForNativeFooting(){var one=new FishingOffenseProfile(profile.itemId(),profile.itemName(),profile.itemLore(),profile.targetType(),profile.abilityReceiptTemplate(),100,100L,200L,5000L,1);var c=new FishingOffenseController();c.start(ready(0),one,100);c.tick(ready(1),100);c.tick(ready(2),100);c.tick(ready(100),100);c.tick(footing(frame(101,true,false,true,true,200,2,1,10,82,1,1,false,false,false),false),100);c.tick(footing(frame(102,true,false,true,true,200,2,1,10,82,1,1,false,false,false),false),100);c.tick(footing(frame(103,true,false,false,true,200,2,1,10,82,1,1,true,false,false),false),100);return c;}
    @Test void releasesWhileAirborneThenStartsOnlyOnActualSupportedSettledFooting(){var c=waitingForNativeFooting();assertEquals(FishingOffenseController.State.WAIT_FOOTING,c.state());for(int time=104;time<200;time++)assertEquals(WAIT_FOOTING,c.tick(footing(frame(time,true,false,false,true,200,2,1,10,82,1,1,true,false,false),false),100));assertEquals(RETURN,c.tick(frame(200,true,false,false,true,200,2,1,10,82,1,1,true,false,false),100));assertEquals(FishingOffenseController.State.RETURN,c.state());assertEquals(1,c.uses());}
    @Test void waitingNeverExtendsOriginalReturnDeadline(){var c=waitingForNativeFooting();assertEquals(WAIT_FOOTING,c.tick(footing(frame(5101,true,false,false,true,200,2,1,10,82,1,1,true,false,false),false),100));assertEquals(RELEASE,c.tick(footing(frame(5102,true,false,false,true,200,2,1,10,82,1,1,true,false,false),false),100));assertTrue(c.failure().contains("deadline"));assertEquals(1,c.uses());}
    @Test void waitingFootingPreemptionCannotIssueLaterGroundReturn(){var c=waitingForNativeFooting();c.cancel();assertEquals(NONE,c.tick(frame(200,true,false,false,true,200,2,1,10,82,1,1,true,true,true),100));assertFalse(c.start(ready(1000),profile,100));}
    @Test void waitingFootingStillRejectsChangedNativeContext(){var c=waitingForNativeFooting();assertEquals(RELEASE,c.tick(footing(frame(200,false,false,false,true,200,2,1,10,82,1,1,true,false,false),false),100));assertTrue(c.failure().contains("context"));}
    @Test void sourceExactManaBoundaryAndUnknown(){for(Integer mana:new Integer[]{null,299}){var c=new FishingOffenseController();assertFalse(c.start(frame(0,true,false,false,true,mana,1,0,20,0,1,1,true,true,true),profile,100));}assertTrue(new FishingOffenseController().start(ready(0),profile,100));}
    @Test void sourceStrictUseRange(){assertFalse(new FishingOffenseController().start(frame(0,true,false,false,true,300,1,0,20,0,4,0,true,true,true),profile,100));assertFalse(new FishingOffenseController().start(frame(0,true,false,false,true,300,1,0,20,0,0,6,true,true,true),profile,100));}
    @Test void staleManaAndOwnerRejectStart(){assertFalse(new FishingOffenseController().start(frame(0,true,false,false,false,300,1,0,20,0,0,0,true,true,true),profile,100));assertFalse(new FishingOffenseController().start(frame(0,false,false,false,true,300,1,0,20,0,0,0,true,true,true),profile,100));}
    @Test void reelOnceAndWaitActualRemoval(){var c=new FishingOffenseController();var f=frame(0,true,true,false,true,300,1,0,20,0,1,1,true,true,true);assertTrue(c.start(f,profile,100));assertEquals(REEL,c.tick(f,100));assertEquals(NONE,c.tick(f,100));assertEquals(NONE,c.tick(f,100));assertEquals(SELECT,c.tick(frame(50,true,false,false,true,300,1,0,20,0,1,1,true,true,true),100));}
    @Test void actualPitchAt82AndPacing(){var c=started();assertEquals(AIM_DOWN,c.tick(frame(99,true,false,true,true,300,1,0,20,81.99f,1,1,false,true,false),100));assertEquals(NONE,c.tick(ready(99),100));assertEquals(USE,c.tick(ready(100),100));assertEquals(NONE,c.tick(ready(101),100));}
    @Test void guardDoesNotBroadenTracking6ToUse4(){var c=started();assertEquals(RELEASE,c.tick(frame(100,true,false,true,true,300,1,0,20,82,4,1,false,false,false),100));assertFalse(c.failure().isEmpty());}
    @Test void independentlyFreshManaAbilityAndTargetHealthRequired(){var c=started();assertEquals(USE,c.tick(ready(100),100));assertEquals(NONE,c.tick(frame(101,true,false,true,true,200,1,1,10,82,1,1,false,true,false),100));assertEquals(NONE,c.tick(frame(102,true,false,true,true,200,2,0,10,82,1,1,false,true,false),100));assertEquals(NONE,c.tick(frame(103,true,false,true,true,200,2,1,20,82,1,1,false,true,false),100));assertEquals(FishingOffenseController.State.RECEIPT,c.state());}
    @Test void wrongManaDeltaDoesNotAcknowledge(){var c=started();c.tick(ready(100),100);c.tick(frame(101,true,false,true,true,201,2,1,10,82,1,1,false,true,false),100);assertEquals(0,c.uses());}
    @Test void boundedSecondUseCannotSpendBelowSource300(){var c=started();c.tick(ready(100),100);c.tick(frame(101,true,false,true,true,200,2,1,10,82,1,1,false,true,false),100);assertEquals(1,c.uses());assertEquals(RELEASE,c.tick(frame(201,true,false,true,true,200,3,1,10,82,1,1,false,true,false),100));assertEquals(1,c.uses());}
    @Test void fullReceiptsReturnRodSpotViewBeforeCompletion(){var one=new FishingOffenseProfile(profile.itemId(),profile.itemName(),profile.itemLore(),profile.targetType(),profile.abilityReceiptTemplate(),100,100L,200L,5000L,1);var c=new FishingOffenseController();c.start(ready(0),one,100);c.tick(ready(1),100);c.tick(ready(2),100);c.tick(ready(100),100);c.tick(frame(101,true,false,true,true,200,2,1,10,82,1,1,false,false,false),100);assertEquals(RESTORE_SLOT,c.tick(frame(102,true,false,true,true,200,2,1,10,82,1,1,false,false,false),100));assertEquals(RETURN,c.tick(frame(103,true,false,false,true,200,2,1,10,82,1,1,true,false,false),100));assertEquals(RETURN,c.tick(frame(104,true,false,false,true,200,2,1,10,82,1,1,true,false,false),100));assertEquals(RESTORE_VIEW,c.tick(frame(105,true,false,false,true,200,2,1,10,82,1,1,true,true,false),100));assertEquals(RESTORE_VIEW,c.tick(frame(106,true,false,false,true,200,2,1,10,82,1,1,true,true,false),100));assertEquals(RELEASE,c.tick(frame(107,true,false,false,true,200,2,1,10,82,1,1,true,true,true),100));assertEquals(FishingOffenseController.State.COMPLETE,c.state());}
    @Test void receiptTimeoutDoesNotRepeatUse(){var c=started();assertEquals(USE,c.tick(ready(100),100));assertEquals(RELEASE,c.tick(ready(5101),100));assertEquals(NONE,c.tick(ready(5102),100));assertEquals(0,c.uses());}
    @Test void manualSlotChangeAndPreemptionRelease(){var c=started();assertEquals(RELEASE,c.tick(frame(50,true,false,false,true,300,1,0,20,0,1,1,true,true,true),100));var d=started();assertEquals(RELEASE,d.tick(frame(50,false,false,true,true,300,1,0,20,82,1,1,false,false,false),100));}
    @Test void cancellationCannotReacquireDuringCleanup(){var c=started();c.cancel();assertEquals(NONE,c.tick(ready(1000),100));assertFalse(c.start(ready(1000),profile,100));c.reset();assertTrue(c.start(ready(1000),profile,100));}
    @Test void profileRejectsUnknownZeroManaOpaqueBlazeAndUnboundReceipt(){assertThrows(IllegalArgumentException.class,()->FishingOffenseProfile.parse("{}"));assertThrows(IllegalArgumentException.class,()->new FishingOffenseProfile(profile.itemId(),profile.itemName(),profile.itemLore(),profile.targetType(),profile.abilityReceiptTemplate(),0,100L,200L,5000L,1));assertThrows(IllegalArgumentException.class,()->new FishingOffenseProfile(profile.itemId(),profile.itemName(),profile.itemLore(),"minecraft:blaze",profile.abilityReceiptTemplate(),100,100L,200L,5000L,1));assertThrows(IllegalArgumentException.class,()->new FishingOffenseProfile(profile.itemId(),profile.itemName(),profile.itemLore(),profile.targetType(),"Skill",100,100L,200L,5000L,1));}
    @Test void invalidPitchAndGeometryCannotUse(){var c=started();assertEquals(RELEASE,c.tick(frame(100,true,false,true,true,300,1,0,20,82,Double.NaN,1,false,false,false),100));}
    @Test void lateOwnedHookBeforeToolSelectionReelsExactlyOnce(){var c=new FishingOffenseController();var empty=frame(0,true,false,false,true,300,1,0,20,0,1,1,true,true,true);assertTrue(c.start(empty,profile,100));assertEquals(NONE,c.tick(empty,100));var late=frame(10,true,true,false,true,300,1,0,20,0,1,1,true,true,true);assertEquals(REEL,c.tick(late,100),"Late owned cast receipt must be reeled before temporary tool selection");assertEquals(NONE,c.tick(late,100));assertEquals(NONE,c.tick(late,100));assertEquals(SELECT,c.tick(frame(20,true,false,false,true,300,1,0,20,0,1,1,true,true,true),100));}
    @Test void lateHookAfterToolSelectionCannotIssueAbility(){var c=started();assertEquals(RELEASE,c.tick(frame(100,true,true,true,true,300,1,0,20,82,1,1,false,false,false),100));assertTrue(c.failure().contains("hook"));assertEquals(0,c.uses());}
}
